information_architecture_ui <- function(id) { ns<-NS(id); lab_section(c("Group content by meaning.","Make labels recognisable to a visitor.","Consider where a page belongs in a hierarchy."), tagList(p("Challenge · Organise a small university course site."), fluidRow(column(5, selectInput(ns("card"),"Content card",c("Course overview","Weekly readings","Assessment dates","Contact tutor","Class forum","Lecture recordings")), textInput(ns("category"),"Category label",placeholder="e.g. Learn"), actionButton(ns("place"),"Place card",class="btn-primary")), column(7, h4("Your draft sitemap",style="font-family:Georgia"), uiOutput(ns("map")), actionButton(ns("reset"),"Reset activity",class="btn-outline-secondary")))), "Would a first-time student predict these labels? Which card could fit more than one place?") }
information_architecture_server <- function(id) { moduleServer(id,function(input,output,session){ placed<-reactiveVal(data.frame(card=character(),category=character())); observeEvent(input$place,{req(nzchar(input$category)); x<-placed(); x<-rbind(x,data.frame(card=input$card,category=trimws(input$category))); placed(x)}); observeEvent(input$reset,placed(data.frame(card=character(),category=character()))); output$map<-renderUI({x<-placed(); if(!nrow(x)) return(p(class="muted","Add a card and category to begin.")); groups<-split(x$card,x$category); tagList(lapply(names(groups),function(g) div(class="wire-item",tags$strong(g),tags$ul(lapply(groups[[g]],tags$li)))))}) }) }
